import{_ as i,h as l,i as e,c as d,v as o,p as s,x as r,m as n,e as A,S as U}from"./chunks/framework.Dvtg8yj2.js";const m=JSON.parse('{"title":"统一总线 UB 灵衢：内存语义 + 消息语义","description":"","frontmatter":{"title":"统一总线 UB 灵衢：内存语义 + 消息语义","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ub-lingqu.md","filePath":"llm/ub-lingqu.md","lastUpdated":1788454257000}'),C={name:"llm/ub-lingqu.md"};function B(P,a,p,c,h,E){const t=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="统一总线-ub-灵衢-内存语义-消息语义" tabindex="-1">统一总线 UB 灵衢：内存语义 + 消息语义 <a class="header-anchor" href="#统一总线-ub-灵衢-内存语义-消息语义" aria-label="Permalink to &quot;统一总线 UB 灵衢：内存语义 + 消息语义&quot;">​</a></h1><div class="epigraph"><p>UB 同时支持同步的 Load/Store/Atomic 与异步的 Read/Write/Message，于是 CPU、NPU 与交换可以用同一套 IO 控制器，而不再把 PCIe、NVLink、RDMA 三种协议叠在一条数据路径上。</p><footer>—— UB-Mesh 论文对 Unified Bus 的公开界定；协议细节当时声明将另行发布</footer></div><p>灵衢是华为对统一总线（Unified Bus, UB）的产品名。在 <a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 里，UB 平面把 384 颗 910C 与 192 颗鲲鹏收进同一张高带宽网，承担 Scale-Up。它要解决的不是「再做一种更快的以太网」，而是把传统 AI 集群里<strong>分裂的三种互连</strong>合成一种：主机到设备的 PCIe、设备之间的专用链、节点之间的 RDMA。UB-Mesh 论文写明：UB 同时提供内存语义与消息语义；基于 UB，CPU、NPU 乃至低基数交换（LRS）可以复用同一套 IO 控制器。本篇只写这一对语义对软件意味着什么。论文脚注写过协议规格将另行发布——未发布的包头、链路编码、重传状态机，本文不编。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 集群的数据路径是拼出来的：CPU 与 GPU 之间 PCIe，节点内 GPU 之间 NVLink，跨节点 InfiniBand 或 RoCE。每跨一次协议，就要转换、排队、换地址空间。LLM 的 TP All-Reduce、MoE All-to-All、以及把 KV 放到主机 DRAM 再取回，会反复穿过这些边界。编程模型也分裂：CUDA 统一内存、NVLink SHARP、NCCL、ibverbs 各管一段。昇腾若只在节点内保留 HCCS、节点间再挂 RoCE，则超节点仍然是「很多台服务器」，CPU 内存不能作为 NPU 的一等公民。</p><p>UB 要回答：同一套链路能否既像总线一样被处理器发出 Load/Store，又像网络一样发消息、做 RDMA 式的 Read/Write？若只能消息，池化内存就要走显式拷贝；若只能一致性 Load/Store，跨柜规模和故障隔离会变得像一台巨大 SMP，难以工程化。公开设计选择了<strong>两者都要</strong>。</p><h3 id="两种语义不是两个网" tabindex="-1">两种语义不是两个网 <a class="header-anchor" href="#两种语义不是两个网" aria-label="Permalink to &quot;两种语义不是两个网&quot;">​</a></h3><p>内存语义：同步 Load/Store/Atomic，适合小粒度、需要顺序与原子的访问，例如锁、计数、控制块。消息语义：异步 Read/Write/Message，适合大块张量、集合通信、KV 页搬运。它们共享物理链路与 IO 控制器，靠操作类型分流，而不是柜顶两套线。把 UB 理解成「就是 RDMA 改个名」，会丢掉 Load/Store；理解成「就是把 HCCS 拉长」，会丢掉消息与多跳交换。正确的心理模型是：域内一种控制器，两种访问动词。</p><p><span class="marginnote">UB-Mesh 论文把协议详细规格标为将发布。因此不要在容量规划里填写未出现在 CloudMatrix384 / UB-Mesh 论文中的单通道比特率编码方案，或发明一种「灵衢 opcode 表」。已公开的是语义类别与系统级带宽，不是芯片手册级的包格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件分层应对齐语义，而不是对齐旧网卡驱动名。</p><p>集合通信（HCCL 的 All-Reduce、All-to-All）应走消息语义：大块、异步、可与计算重叠。这是 TP / EP 的主路径。池化 DRAM 与远端 HBM 上的 KV、权重暂驻，可用异步 Read/Write，把「内存池」做成服务，而不是每个 worker 自己 mmap 一张跨 16 柜的共享虚拟地址——后者是否对程序员暴露，要以当时编程指南为准，本文不发明机柜级 <code>malloc</code>。控制面的轻量同步（队列头、完成标记）才考虑 Atomic / Store。昇腾 AI Core 上，公开材料还描述过用 MTE（memory transfer engine）做远程大块搬移：那是面向 AI 的异步类 Load/Store，不是 GPU 上那种同步标量 Load。把它当成 CUDA <code>ld</code> 会在延迟隐藏上判断失误。</p><p>三平面分工见 CloudMatrix384：UB 平面给超节点内 Scale-Up；RDMA 平面给超节点间；VPC 给管控与存储。UB 的内存+消息只承诺在超节点域内。跨超节点仍用 RoCE，不要把灵衢动词套到对象存储路径上。</p>',13)),(e(),s(U,null,{default:r(()=>[A(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20UB%5B%22UB%20%E7%81%B5%E8%A1%A2%20%E8%B6%85%E8%8A%82%E7%82%B9%E5%9F%9F%22%5D%0A%20%20%20%20LS%5B%22%E5%86%85%E5%AD%98%E8%AF%AD%E4%B9%89%20Load%2FStore%2FAtomic%22%5D%0A%20%20%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E8%AF%AD%E4%B9%89%20Read%2FWrite%2FMessage%22%5D%0A%20%20end%0A%20%20CPU%5B%22%E9%B2%B2%E9%B9%8F%22%5D%20--%3E%20LS%0A%20%20CPU%20--%3E%20MSG%0A%20%20NPU%5B%22910C%22%5D%20--%3E%20LS%0A%20%20NPU%20--%3E%20MSG%0A%20%20SW%5B%22L1%2FL2%20%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20MSG%0A%20%20MSG%20--%3E%20TP%5B%22TP%20%2F%20EP%20%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%5D%0A%20%20MSG%20--%3E%20KV%5B%22%E6%B1%A0%E5%8C%96%20KV%20%2F%20%E6%9D%83%E9%87%8D%E6%90%AC%E8%BF%90%22%5D%0A%20%20LS%20--%3E%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%9D%97%E4%B8%8E%E5%8E%9F%E5%AD%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="控制器复用带来的资源池化" tabindex="-1">控制器复用带来的资源池化 <a class="header-anchor" href="#控制器复用带来的资源池化" aria-label="Permalink to &quot;控制器复用带来的资源池化&quot;">​</a></h3><p>因为 CPU、NPU、交换都讲 UB，带宽分配可以从「PCIe 固定几条、NVLink 固定几条」变成在同一组链路上按负载切：论文把这写成灵活 IO 分配与硬件资源池化。CloudMatrix 愿景里的四件事——跨节点 TP/EP、按负载组合 CPU/NPU/内存、AI 与数据密集融合、CPU DRAM 聚成内存级存储——都依赖「NPU 不必经过 CPU 才能碰到另一颗 NPU 或远端 DRAM」。当前 384 仍是每节点 8+4 的物理配比，池化是逻辑的；物理上拆成纯 CPU 柜与纯 NPU 柜是论文中的未来方向。</p><p><span class="marginnote">「点对点、无需 CPU 中介」指数据面。固件、驱动、MatrixLink 代理仍跑在节点上，擎天卡仍做南北向。不要写成超节点里没有 CPU 也可以启动 OS。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传统混合互连的税在协议转换：GPU 上的张量要变成 RDMA 工作请求，再在对端变回设备内存。UB 域内同一控制器，减少转换与多次排队。消息语义的大块搬运可以对齐 Cube 的砖块大小；内存语义的原子保证控制面不靠以太网往返。L1/L2 交换转发的是 UB 包，对上仍是这两种动词，所以跨柜之后软件接口可以不变，变的是跳数与是否走光模块。</p><p>延迟隐藏因此要按动词选。同步 Load 跨柜会把核卡住，不适合热路径上的逐元素访问；decode 的 KV 应按块异步 Read 进近端 HBM。这与 GPU 上「不要在 kernel 里远程硬读整段 KV」是同一条纪律，只是远程从 NVLink 换成了 UB。</p><h3 id="与-hccs、rdma-的接缝" tabindex="-1">与 HCCS、RDMA 的接缝 <a class="header-anchor" href="#与-hccs、rdma-的接缝" aria-label="Permalink to &quot;与 HCCS、RDMA 的接缝&quot;">​</a></h3><p>节点内历史上的 <a href="/llm/hccs-to-ub">HCCS</a> 提供缓存一致性，面向 8 卡盒。UB 把域撑到多柜，一致性边界与消息边界如何划，以公开文档为准：不要假设 384 颗 NPU 共享一个单一 cache-coherent 地址空间。RDMA 平面在 384 上仍然独立，保证与标准 RDMA 栈互操作；UB 不是把 RoCE 废掉，而是把最密的那一档通信收进超节点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 UB 替代数据中心网络：检查点、跨 AZ、对象存储仍走 VPC/RDMA。不要在未提供统一编址 API 的软件栈里手写跨柜指针。不要把 UB-Mesh 论文里相对 Clos 的成本倍数（例如光模块减少比例）当成 CloudMatrix 384 机房的采购清单——那是架构论文相对基线的估计。协议未公开部分，驱动与 HCCL 版本必须与超节点固件绑定，自行解析包等于在未授权层上工作。</p><p>对框架，HCCL 仍是集合通信入口；下面走 UB 还是 RoCE，由进程组是否落在同一超节点决定。选错平面，语义还在，屋顶线差一档。</p><p><span class="marginnote">出处：arXiv:2503.20377 UB-Mesh 文中 Unified Bus 的同步/异步操作分类与控制器复用；arXiv:2506.12708 CloudMatrix384 对 UB 平面能力的描述。不引用未发布的 UB 协议规范正文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>灵衢 UB 在超节点内同时提供内存语义（Load/Store/Atomic）与消息语义（Read/Write/Message）。</li><li>一种 IO 控制器覆盖 CPU、NPU 与交换，才能做资源池化、少协议转换。</li><li>TP/EP 与大块 KV 走异步消息；控制块才用同步原子。AI Core 上的远程搬移是异步大块，不是标量 Load。</li><li>域外仍是 RDMA 与 VPC；UB 不消灭以太网。</li><li>协议细节未公开则不编；软件以 HCCL 与厂商编程指南为准。</li><li>出处：UB-Mesh 与 CloudMatrix384 公开论文。</li></ul>',14))])}const M=i(C,[["render",B]]);export{m as __pageData,M as default};
